  desc "Local gateway between AI clients and MCP servers"
  homepage "https://github.com/dinstein/homebrew-agenthub"
  version "0.12.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/dinstein/homebrew-agenthub/releases/download/v0.12.0/agenthub-0.12.0-ca7c72f-darwin-arm64.tar.gz"
      sha256 "61fe9ac782fbb4b8e6366373eab39b509a82e5afb731dd51bf630db64490d782"
    end
    on_intel do
      url "https://github.com/dinstein/homebrew-agenthub/releases/download/v0.12.0/agenthub-0.12.0-ca7c72f-darwin-amd64.tar.gz"
      sha256 "5303623a692979952f7a3e5a29da5844bec0b2e0bb3b40ef972a732774a1eb0f"
